#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    int maxConcatenatedValue(std::vector<std::string>& segments) {
        const int MOD = 1e9 + 7;
        std::sort(segments.begin(), segments.end(), [](const std::string& a, const std::string& b) {
            return a + b > b + a;
        });
        long long val = 0;
        for (const auto& seg : segments) {
            for (char c : seg) {
                val = ((val << 1) | (c - '0')) % MOD;
            }
        }
        return val;
    }
};

import java.util.*;

class Solution {
    public int maxConcatenatedValue(String[] segments) {
        int MOD = 1_000_000_007;
        Arrays.sort(segments, (a, b) -> (b + a).compareTo(a + b));
        long val = 0;
        for (String seg : segments) {
            for (char c : seg.toCharArray()) {
                val = ((val << 1) | (c - '0')) % MOD;
            }
        }
        return (int) val;
    }
}

function maxConcatenatedValue(segments) {
    const MOD = 1000000007n;
    segments.sort((a, b) => (b + a).localeCompare(a + b));
    let val = 0n;
    for (const seg of segments) {
        for (let i = 0; i < seg.length; i++) {
            val = ((val << 1n) | BigInt(seg[i])) % MOD;
        }
    }
    return Number(val);
}
